"use client"

/**
 * Clean-room workstream Gantt.
 * The host owns the items. onSelect and onHover report intent and do not write.
 * Hover opens tooltip-card. Arrow keys move between bars. The header stays put while the scale scrolls.
 * Dates are UTC calendar days. Spanish chrome is the default.
 */

import * as React from "react"
import { motion, useReducedMotion } from "motion/react"

import { Button } from "@/components/ui/button"
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from "@/components/ui/empty"
import { Skeleton } from "@/components/ui/skeleton"
import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"
import {
  GANTT_DAY_WIDTH,
  GANTT_GROUP_HEIGHT,
  GANTT_LABEL_WIDTH,
  GANTT_ROW_HEIGHT,
  GANTT_SCALES,
  dependencyCurve,
  formatGanttDate,
  ganttBar,
  ganttDependencies,
  ganttDomain,
  ganttTicks,
  isUtcWeekend,
  layoutGroups,
  timelineWidth,
  todayOffset,
  withGanttLabels,
  type GanttItem,
  type GanttScale,
  type GanttStatus,
  type GanttWorkstream,
  type TimelineGanttLabels,
} from "@/lib/timeline-gantt"
import { TooltipCard } from "@/components/ui/tooltip-card"

const barTone: Record<GanttStatus, string> = {
  planned: "bg-muted text-foreground",
  active: "bg-primary text-primary-foreground",
  blocked: "bg-destructive text-background",
  done: "bg-foreground text-background",
  "at-risk": "bg-chart-4 text-foreground",
}

const subscribe = () => () => {}

function useReducedFlag() {
  const hydrated = React.useSyncExternalStore(subscribe, () => true, () => false)
  return !!useReducedMotion() && hydrated
}

export type TimelineGanttClassNames = {
  toolbar?: string
  label?: string
  header?: string
  bar?: string
  today?: string
}

export type TimelineGanttProps<TMeta = Record<string, unknown>> = {
  items: readonly GanttItem<TMeta>[]
  workstreams?: readonly GanttWorkstream[]
  scale?: GanttScale
  defaultScale?: GanttScale
  onScaleChange?: (scale: GanttScale) => void
  now?: string
  locale?: string
  weekStartsOn?: number
  labelWidth?: number
  selectedId?: string | null
  onSelect?: (item: GanttItem<TMeta>) => void
  onHover?: (item: GanttItem<TMeta> | null) => void
  labels?: Partial<TimelineGanttLabels>
  loading?: boolean
  error?: string | null
  onRetry?: () => void
  disabled?: boolean
  /** Keeps the name for assistive tech without a second visible title. */
  hideHeading?: boolean
  className?: string
  classNames?: TimelineGanttClassNames
  renderDetail?: (item: GanttItem<TMeta>) => React.ReactNode
}

export function TimelineGantt<TMeta = Record<string, unknown>>({
  items,
  workstreams,
  scale: scaleProp,
  defaultScale = "week",
  onScaleChange,
  now,
  locale = "es-MX",
  weekStartsOn = 1,
  labelWidth = GANTT_LABEL_WIDTH,
  selectedId,
  onSelect,
  onHover,
  labels,
  loading = false,
  error = null,
  onRetry,
  disabled = false,
  hideHeading = false,
  className,
  classNames,
  renderDetail,
}: TimelineGanttProps<TMeta>) {
  const copy = withGanttLabels(labels)
  const reduced = useReducedFlag()
  const [uncontrolledScale, setUncontrolledScale] = React.useState<GanttScale>(defaultScale)
  const scale = scaleProp ?? uncontrolledScale
  const [clock] = React.useState(() => now ?? new Date().toISOString())
  const nowIso = now ?? clock
  const [openId, setOpenId] = React.useState<string | null>(null)
  const openRef = React.useRef<string | null>(null)
  const [cursor, setCursor] = React.useState<string | null>(null)
  const [announcement, setAnnouncement] = React.useState("")
  const headingId = React.useId()

  const dayWidth = GANTT_DAY_WIDTH[scale]
  const nowMs = Date.parse(nowIso)
  const domain = React.useMemo(
    () => ganttDomain(items, scale, Number.isFinite(nowMs) ? nowMs : Date.UTC(2026, 0, 1), weekStartsOn),
    [items, scale, nowMs, weekStartsOn],
  )
  const width = timelineWidth(domain, dayWidth)
  const ticks = React.useMemo(
    () => ganttTicks(domain, scale, locale, dayWidth, weekStartsOn),
    [domain, scale, locale, dayWidth, weekStartsOn],
  )
  const layout = React.useMemo(
    () => layoutGroups(items, workstreams, GANTT_ROW_HEIGHT, GANTT_GROUP_HEIGHT),
    [items, workstreams],
  )
  const links = React.useMemo(() => ganttDependencies(items), [items])
  const byId = React.useMemo(() => new Map(items.map((item) => [item.id, item])), [items])
  const today = todayOffset(nowIso, domain, dayWidth)
  const taskOrder = layout.groups.flatMap((group) => group.tasks.map((task) => task.id))
  const activeId = selectedId ?? cursor ?? taskOrder[0] ?? null
  const columns = `${labelWidth}px ${width}px`

  function commitScale(next: GanttScale) {
    if (scaleProp === undefined) setUncontrolledScale(next)
    onScaleChange?.(next)
  }

  function setOpen(id: string, next: boolean) {
    const resolved = next ? id : openRef.current === id ? null : openRef.current
    openRef.current = resolved
    setOpenId(resolved)
    onHover?.(resolved ? (byId.get(resolved) ?? null) : null)
  }

  function moveFocus(fromId: string, key: string) {
    const index = taskOrder.indexOf(fromId)
    if (index < 0) return
    let next = index
    if (key === "ArrowDown") next = Math.min(taskOrder.length - 1, index + 1)
    else if (key === "ArrowUp") next = Math.max(0, index - 1)
    else if (key === "Home") next = 0
    else if (key === "End") next = taskOrder.length - 1
    else return
    const id = taskOrder[next]
    if (!id) return
    setCursor(id)
    document.getElementById(barDomId(headingId, id))?.focus()
  }

  const placed = new Map<string, { x: number; width: number; y: number }>()
  for (const group of layout.groups) {
    for (const task of group.tasks) {
      const item = items[task.index]
      if (!item) continue
      const bar = ganttBar(item, domain, dayWidth)
      if (bar) placed.set(item.id, { x: bar.x, width: bar.width, y: task.y })
    }
  }

  return (
    <section
      aria-labelledby={headingId}
      data-slot="timeline-gantt"
      data-scale={scale}
      data-disabled={disabled ? "true" : "false"}
      data-reduced-motion={reduced ? "true" : "false"}
      className={cn("flex h-full min-h-0 min-w-0 flex-col gap-2 text-foreground", className)}
    >
      <div className={cn("flex flex-wrap items-center justify-between gap-2", classNames?.toolbar)}>
        <h2 id={headingId} className={cn("text-sm font-medium", hideHeading && "sr-only")}>
          {copy.heading}
        </h2>
        <div role="group" aria-label={copy.scaleLabel} className="flex gap-1">
          {GANTT_SCALES.map((option) => (
            <button
              key={option}
              type="button"
              aria-pressed={scale === option}
              disabled={disabled}
              className={cn(
                "rounded-md border px-2 py-1 text-xs outline-none focus-visible:ring-3 focus-visible:ring-ring",
                scale === option ? "border-border bg-muted text-foreground" : "border-transparent text-muted-foreground",
              )}
              onClick={() => commitScale(option)}
            >
              {copy[option]}
            </button>
          ))}
        </div>
      </div>
      {disabled ? <p className="text-xs text-muted-foreground">{copy.disabledNote}</p> : null}
      {loading ? (
        <div className="flex flex-col gap-2" aria-busy="true" aria-live="polite">
          <span className="sr-only">{copy.loading}</span>
          <Skeleton className="h-8 w-full" />
          <Skeleton className="h-24 w-full" />
          <Skeleton className="h-24 w-full" />
        </div>
      ) : error ? (
        <div role="alert" className="flex flex-col items-start gap-2 rounded-lg border border-border p-4">
          <p className="text-sm font-medium">{copy.errorTitle}</p>
          <p className="text-sm text-muted-foreground break-words [overflow-wrap:anywhere]">{error}</p>
          {onRetry ? (
            <Button type="button" size="sm" variant="outline" onClick={onRetry}>
              {copy.retry}
            </Button>
          ) : null}
        </div>
      ) : items.length === 0 ? (
        <Empty className="min-h-48 border border-dashed">
          <EmptyHeader>
            <EmptyTitle>{copy.emptyTitle}</EmptyTitle>
            <EmptyDescription>{copy.emptyHint}</EmptyDescription>
          </EmptyHeader>
        </Empty>
      ) : (
        <div className="min-h-48 flex-1 overflow-auto rounded-lg border border-border">
          <div style={{ width: labelWidth + width }} className="min-w-full">
            <div className={cn("sticky top-0 z-20 grid border-b border-border bg-background", classNames?.header)} style={{ gridTemplateColumns: columns }}>
              <div
                className="sticky start-0 z-30 flex items-end border-r border-border bg-background px-2 pb-1 text-xs font-medium text-muted-foreground"
                style={{ width: labelWidth }}
              >
                {copy.labelColumn}
              </div>
              <div className="relative h-10">
                {ticks.map((tick) => (
                  <div
                    key={tick.id}
                    className="absolute inset-y-0 flex items-end border-r border-border px-1 pb-1 text-[11px] text-muted-foreground"
                    style={{ left: tick.x, width: tick.width }}
                  >
                    <span className="truncate">{tick.label}</span>
                  </div>
                ))}
                {today != null ? (
                  <span
                    className={cn("absolute top-1 -translate-x-1/2 rounded-sm bg-primary px-1 text-[10px] text-primary-foreground", classNames?.today)}
                    style={{ left: today }}
                  >
                    {copy.today}
                  </span>
                ) : null}
              </div>
            </div>
            <div className="relative">
              <div className="pointer-events-none absolute inset-y-0" style={{ left: labelWidth, width }} aria-hidden="true">
                {scale === "day"
                  ? ticks
                      .filter((tick) => isUtcWeekend(tick.start))
                      .map((tick) => (
                        <div key={tick.id} className="absolute inset-y-0 bg-muted/50" style={{ left: tick.x, width: tick.width }} />
                      ))
                  : null}
                {today != null ? <div className="absolute inset-y-0 w-px bg-primary" style={{ left: today }} data-slot="timeline-gantt-today" /> : null}
              </div>
              <svg
                className="pointer-events-none absolute top-0"
                style={{ left: labelWidth, width, height: layout.height }}
                viewBox={`0 0 ${width} ${Math.max(layout.height, 1)}`}
                aria-hidden="true"
              >
                {links.map((link) => {
                  const from = placed.get(link.fromId)
                  const to = placed.get(link.toId)
                  if (!from || !to) return null
                  const curve = dependencyCurve(from, to, GANTT_ROW_HEIGHT)
                  return (
                    <g key={`${link.fromId}-${link.toId}`} data-slot="timeline-gantt-dependency">
                      <path d={curve.d} className="fill-none stroke-muted-foreground" strokeWidth="1.25" />
                      <circle cx={curve.x} cy={curve.y} r="2.5" className="fill-muted-foreground" />
                    </g>
                  )
                })}
              </svg>
              {layout.groups.map((group) => (
                <div key={group.id}>
                  <div className="grid" style={{ gridTemplateColumns: columns }}>
                    <div
                      className="sticky start-0 z-10 flex items-center border-r border-border bg-muted px-2 text-xs font-medium"
                      style={{ width: labelWidth, height: GANTT_GROUP_HEIGHT }}
                    >
                      <span className="truncate">{copy.workstream(group.label, group.tasks.length)}</span>
                    </div>
                    <div className="bg-muted/40" style={{ height: GANTT_GROUP_HEIGHT }} />
                  </div>
                  {group.tasks.map((task) => {
                    const item = items[task.index]
                    if (!item) return null
                    const bar = ganttBar(item, domain, dayWidth)
                    const statusLabel = copy.status[item.status] ?? item.status
                    const startLabel = formatGanttDate(item.start, locale)
                    const endLabel = formatGanttDate(item.end, locale)
                    const depNames = (item.deps ?? []).map((id) => byId.get(id)?.label ?? id)
                    const description = [item.description, depNames.length ? `${copy.dependencies}: ${depNames.join(", ")}` : copy.noDependencies]
                      .filter(Boolean)
                      .join("\n")
                    const button = (
                      <button
                        id={barDomId(headingId, item.id)}
                        type="button"
                        disabled={disabled}
                        tabIndex={activeId === item.id ? 0 : -1}
                        aria-pressed={selectedId === item.id}
                        aria-label={copy.barLabel(item.label, startLabel, endLabel, statusLabel)}
                        data-slot="timeline-gantt-bar"
                        data-status={item.status}
                        data-id={item.id}
                        className={cn(
                          "absolute top-1.5 flex h-7 items-center rounded-md px-2 text-xs font-medium outline-none focus-visible:ring-3 focus-visible:ring-ring",
                          barTone[item.status] ?? barTone.planned,
                          selectedId === item.id && "ring-2 ring-ring",
                          classNames?.bar,
                        )}
                        style={bar ? { left: bar.x, width: bar.width } : undefined}
                        onClick={() => {
                          setCursor(item.id)
                          setAnnouncement(copy.selected(item.label))
                          onSelect?.(item)
                        }}
                        onKeyDown={(event) => {
                          if (event.key === "ArrowDown" || event.key === "ArrowUp" || event.key === "Home" || event.key === "End") {
                            event.preventDefault()
                            moveFocus(item.id, event.key)
                          }
                        }}
                      >
                        <span className={cn("truncate", bar && bar.width < 72 && "sr-only")}>{item.label}</span>
                      </button>
                    )
                    return (
                      <div key={`${item.id}-${task.index}`} className="grid" style={{ gridTemplateColumns: columns }}>
                        <div
                          className={cn(
                            "sticky start-0 z-10 flex items-center border-r border-b border-border bg-background px-2 text-sm",
                            classNames?.label,
                          )}
                          style={{ width: labelWidth, height: GANTT_ROW_HEIGHT }}
                        >
                          <span className="truncate">{item.label}</span>
                        </div>
                        <div className="relative border-b border-border" style={{ height: GANTT_ROW_HEIGHT }}>
                          {bar ? (
                            <motion.div
                              className="absolute inset-x-0 top-0 h-full"
                              initial={reduced ? false : { opacity: 0 }}
                              animate={{ opacity: 1 }}
                              transition={{ duration: reduced ? 0 : motionPresets.duration.fast, ease: motionPresets.ease.enter }}
                            >
                              {disabled ? (
                                button
                              ) : (
                                <TooltipCard
                                  open={openId === item.id}
                                  onOpenChange={(next) => setOpen(item.id, next)}
                                  title={item.label}
                                  eyebrow={group.label}
                                  description={description}
                                  people={item.assignees}
                                  metrics={[
                                    { id: "status", label: copy.statusLabel, value: statusLabel },
                                    { id: "start", label: copy.start, value: startLabel },
                                    { id: "end", label: copy.end, value: endLabel },
                                    ...(item.metrics ?? []),
                                  ]}
                                  actions={onSelect ? [{ id: "open", label: copy.open, onSelect: () => onSelect(item) }] : undefined}
                                  extra={renderDetail?.(item)}
                                >
                                  {button}
                                </TooltipCard>
                              )}
                            </motion.div>
                          ) : (
                            <span className="sr-only">{item.label}</span>
                          )}
                        </div>
                      </div>
                    )
                  })}
                </div>
              ))}
            </div>
          </div>
          <ul className="sr-only">
            {links.map((link) => (
              <li key={`${link.fromId}-${link.toId}`}>{copy.dependency(byId.get(link.fromId)?.label ?? link.fromId, byId.get(link.toId)?.label ?? link.toId)}</li>
            ))}
          </ul>
        </div>
      )}
      <p className="sr-only" aria-live="polite" data-slot="timeline-gantt-announcement">
        {announcement}
      </p>
      <span className="sr-only">{copy.announcements}</span>
    </section>
  )
}

function barDomId(scope: string, id: string) {
  return `${scope}-bar-${id}`
}

/**
 * Clean-room schedule model for a workstream Gantt.
 * Behavior only: no mockup source, copy, colors, or assets.
 * Chrome defaults to Spanish (es-MX). Pass `labels` or `timelineGanttLabelsEn`.
 * Dates are calendar days. `now` may be a full timestamp; the day is read in UTC.
 * `TMeta` is the host payload. This module never reads it.
 */

export const GANTT_SCALES = ["day", "week", "month"] as const

export type GanttScale = (typeof GANTT_SCALES)[number]

export const GANTT_STATUSES = ["planned", "active", "blocked", "done", "at-risk"] as const

export type GanttStatus = (typeof GANTT_STATUSES)[number]

export const GANTT_ROW_HEIGHT = 40

export const GANTT_GROUP_HEIGHT = 32

export const GANTT_LABEL_WIDTH = 176

export const DAY_MS = 86_400_000

export const GANTT_DAY_WIDTH: Record<GanttScale, number> = {
  day: 36,
  week: 16,
  month: 6,
}

export type GanttAssignee = {
  id: string
  name: string
}

export type GanttMetric = {
  id: string
  label: string
  value: string
}

export type GanttItem<TMeta = Record<string, unknown>> = {
  id: string
  workstream: string
  label: string
  /** Inclusive calendar day, YYYY-MM-DD. */
  start: string
  /** Inclusive calendar day, YYYY-MM-DD. */
  end: string
  status: GanttStatus
  deps?: readonly string[]
  description?: string
  assignees?: readonly GanttAssignee[]
  metrics?: readonly GanttMetric[]
  /** Host payload. The gantt never reads it. */
  meta?: TMeta
}

export type GanttWorkstream = {
  id: string
  label: string
}

export type GanttDomain = {
  /** Inclusive UTC midnight. */
  start: number
  /** Exclusive UTC midnight. */
  end: number
}

export type GanttTick = {
  id: string
  start: number
  end: number
  label: string
  x: number
  width: number
}

export type GanttBar = {
  id: string
  x: number
  width: number
  start: number
  end: number
}

export type GanttGroupLayout = {
  id: string
  label: string
  y: number
  height: number
  tasks: { id: string; index: number; y: number; height: number }[]
}

export type GanttDependency = {
  fromId: string
  toId: string
}

export type TimelineGanttLabels = {
  heading: string
  labelColumn: string
  scaleLabel: string
  day: string
  week: string
  month: string
  today: string
  emptyTitle: string
  emptyHint: string
  loading: string
  errorTitle: string
  retry: string
  disabledNote: string
  statusLabel: string
  start: string
  end: string
  dependencies: string
  noDependencies: string
  open: string
  announcements: string
  people: string
  status: Record<GanttStatus, string>
  openItem: (label: string) => string
  barLabel: (label: string, start: string, end: string, status: string) => string
  dependency: (from: string, to: string) => string
  workstream: (label: string, count: number) => string
  selected: (label: string) => string
}

export const timelineGanttLabels: TimelineGanttLabels = {
  heading: "Cronograma",
  labelColumn: "Frentes",
  scaleLabel: "Escala",
  day: "Día",
  week: "Semana",
  month: "Mes",
  today: "Hoy",
  emptyTitle: "No hay tareas en este periodo",
  emptyHint: "Cuando lleguen encargos, aparecen como barras.",
  loading: "Cargando el cronograma",
  errorTitle: "No se pudo mostrar el cronograma",
  retry: "Reintentar",
  disabledNote: "El cronograma está deshabilitado",
  statusLabel: "Estado",
  start: "Inicio",
  end: "Fin",
  dependencies: "Depende de",
  noDependencies: "Sin dependencias",
  open: "Abrir",
  announcements: "Avisos del cronograma",
  people: "Personas",
  status: {
    planned: "Planeado",
    active: "En curso",
    blocked: "Bloqueado",
    done: "Hecho",
    "at-risk": "En riesgo",
  },
  openItem: (label) => `Abrir ${label}`,
  barLabel: (label, start, end, status) => `${label}, ${status}, del ${start} al ${end}`,
  dependency: (from, to) => `${to} depende de ${from}`,
  workstream: (label, count) => `${label}, ${count}`,
  selected: (label) => `${label} seleccionado`,
}

export const timelineGanttLabelsEn: TimelineGanttLabels = {
  heading: "Schedule",
  labelColumn: "Workstreams",
  scaleLabel: "Scale",
  day: "Day",
  week: "Week",
  month: "Month",
  today: "Today",
  emptyTitle: "No tasks in this range",
  emptyHint: "Bars show up here when work is scheduled.",
  loading: "Loading the schedule",
  errorTitle: "The schedule could not be shown",
  retry: "Try again",
  disabledNote: "The schedule is disabled",
  statusLabel: "Status",
  start: "Start",
  end: "End",
  dependencies: "Depends on",
  noDependencies: "No dependencies",
  open: "Open",
  announcements: "Schedule announcements",
  people: "People",
  status: {
    planned: "Planned",
    active: "Active",
    blocked: "Blocked",
    done: "Done",
    "at-risk": "At risk",
  },
  openItem: (label) => `Open ${label}`,
  barLabel: (label, start, end, status) => `${label}, ${status}, ${start} to ${end}`,
  dependency: (from, to) => `${to} depends on ${from}`,
  workstream: (label, count) => `${label}, ${count}`,
  selected: (label) => `${label} selected`,
}

export function withGanttLabels(labels?: Partial<TimelineGanttLabels>): TimelineGanttLabels {
  return { ...timelineGanttLabels, ...labels, status: { ...timelineGanttLabels.status, ...labels?.status } }
}

/** UTC midnight for a YYYY-MM-DD prefix, or null when the day is not real. */
export function utcDay(iso: string): number | null {
  const match = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso)
  if (!match) return null
  const year = Number(match[1])
  const month = Number(match[2])
  const day = Number(match[3])
  const ms = Date.UTC(year, month - 1, day)
  const check = new Date(ms)
  if (check.getUTCFullYear() !== year || check.getUTCMonth() !== month - 1 || check.getUTCDate() !== day) return null
  return ms
}

export function isoDay(ms: number): string {
  return new Date(ms).toISOString().slice(0, 10)
}

export function addUtcDays(ms: number, days: number) {
  return ms + days * DAY_MS
}

export function startOfUtcDay(ms: number) {
  const date = new Date(ms)
  return Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate())
}

export function startOfUtcWeek(ms: number, weekStartsOn = 1) {
  const day = new Date(ms).getUTCDay()
  const delta = (day - weekStartsOn + 7) % 7
  return ms - delta * DAY_MS
}

export function startOfUtcMonth(ms: number) {
  const date = new Date(ms)
  return Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), 1)
}

export function addUtcMonths(ms: number, count: number) {
  const date = new Date(ms)
  return Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + count, 1)
}

export function isUtcWeekend(ms: number) {
  const day = new Date(ms).getUTCDay()
  return day === 0 || day === 6
}

export function formatGanttDate(iso: string, locale: string) {
  const ms = utcDay(iso)
  if (ms == null) return iso
  return new Intl.DateTimeFormat(locale, { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" }).format(ms)
}

export function ganttDomain(
  items: readonly { start: string; end: string }[],
  scale: GanttScale,
  nowMs: number,
  weekStartsOn = 1,
): GanttDomain {
  const stamps: number[] = []
  for (const item of items) {
    const start = utcDay(item.start)
    const end = utcDay(item.end)
    if (start != null) stamps.push(start)
    if (end != null) stamps.push(end)
  }
  const safeNow = Number.isFinite(nowMs) ? nowMs : Date.UTC(2026, 0, 1)
  let first = stamps.length ? Math.min(...stamps) : startOfUtcDay(safeNow)
  let last = stamps.length ? Math.max(...stamps) : first
  if (last < first) last = first
  const near = 45 * DAY_MS
  if (safeNow >= first - near && safeNow <= last + near) {
    const today = startOfUtcDay(safeNow)
    first = Math.min(first, today)
    last = Math.max(last, today)
  }
  if (scale === "month") {
    const start = startOfUtcMonth(first)
    const end = addUtcMonths(startOfUtcMonth(last), 1)
    return { start, end: Math.max(end, addUtcMonths(start, 1)) }
  }
  if (scale === "week") {
    const start = startOfUtcWeek(addUtcDays(first, -7), weekStartsOn)
    const end = addUtcDays(startOfUtcWeek(last, weekStartsOn), 14)
    return { start, end }
  }
  return { start: addUtcDays(first, -1), end: addUtcDays(last, 2) }
}

export function timelineWidth(domain: GanttDomain, dayWidth: number) {
  const days = Math.max(1, Math.round((domain.end - domain.start) / DAY_MS))
  return days * dayWidth
}

export function ganttTicks(
  domain: GanttDomain,
  scale: GanttScale,
  locale: string,
  dayWidth: number,
  weekStartsOn = 1,
): GanttTick[] {
  const ticks: GanttTick[] = []
  const guard = 500
  if (scale === "day") {
    let cursor = domain.start
    for (let count = 0; cursor < domain.end && count < guard; count += 1) {
      ticks.push({
        id: isoDay(cursor),
        start: cursor,
        end: cursor + DAY_MS,
        label: new Intl.DateTimeFormat(locale, { weekday: "narrow", day: "numeric", timeZone: "UTC" }).format(cursor),
        x: ((cursor - domain.start) / DAY_MS) * dayWidth,
        width: dayWidth,
      })
      cursor += DAY_MS
    }
    return ticks
  }
  if (scale === "week") {
    let cursor = startOfUtcWeek(domain.start, weekStartsOn)
    for (let count = 0; cursor < domain.end && count < guard; count += 1) {
      const weekEnd = addUtcDays(cursor, 7)
      const start = Math.max(cursor, domain.start)
      const end = Math.min(weekEnd, domain.end)
      if (end > start) {
        ticks.push({
          id: isoDay(start),
          start,
          end,
          label: new Intl.DateTimeFormat(locale, { day: "numeric", month: "short", timeZone: "UTC" }).format(start),
          x: ((start - domain.start) / DAY_MS) * dayWidth,
          width: ((end - start) / DAY_MS) * dayWidth,
        })
      }
      cursor = weekEnd
    }
    return ticks
  }
  let cursor = startOfUtcMonth(domain.start)
  for (let count = 0; cursor < domain.end && count < guard; count += 1) {
    const next = addUtcMonths(cursor, 1)
    const start = Math.max(cursor, domain.start)
    const end = Math.min(next, domain.end)
    if (end > start) {
      ticks.push({
        id: isoDay(cursor),
        start,
        end,
        label: new Intl.DateTimeFormat(locale, { month: "short", year: "numeric", timeZone: "UTC" }).format(cursor),
        x: ((start - domain.start) / DAY_MS) * dayWidth,
        width: ((end - start) / DAY_MS) * dayWidth,
      })
    }
    cursor = next
  }
  return ticks
}

export function ganttBar(
  item: { id: string; start: string; end: string },
  domain: GanttDomain,
  dayWidth: number,
): GanttBar | null {
  const start = utcDay(item.start)
  let end = utcDay(item.end)
  if (start == null || end == null) return null
  if (end < start) end = start
  const exclusive = end + DAY_MS
  const x = ((start - domain.start) / DAY_MS) * dayWidth
  const width = Math.max(dayWidth * 0.7, ((exclusive - start) / DAY_MS) * dayWidth - 6)
  return { id: item.id, x, width, start, end: exclusive }
}

export function todayOffset(nowIso: string, domain: GanttDomain, dayWidth: number): number | null {
  const day = utcDay(nowIso)
  if (day == null || day < domain.start || day >= domain.end) return null
  const parsed = Date.parse(nowIso)
  const fraction = Number.isFinite(parsed) ? Math.min(1, Math.max(0, (parsed - day) / DAY_MS)) : 0
  return ((day - domain.start) / DAY_MS + fraction) * dayWidth
}

export function groupWorkstreams<T extends { workstream: string }>(
  items: readonly T[],
  workstreams?: readonly GanttWorkstream[],
) {
  const listed = new Set((workstreams ?? []).map((stream) => stream.id))
  const labels = new Map((workstreams ?? []).map((stream) => [stream.id, stream.label]))
  const order: string[] = []
  const groups = new Map<string, number[]>()
  for (const stream of workstreams ?? []) {
    if (groups.has(stream.id)) continue
    order.push(stream.id)
    groups.set(stream.id, [])
  }
  items.forEach((item, index) => {
    if (!groups.has(item.workstream)) {
      order.push(item.workstream)
      groups.set(item.workstream, [])
    }
    groups.get(item.workstream)?.push(index)
  })
  return order
    .filter((id) => (groups.get(id)?.length ?? 0) > 0 || listed.has(id))
    .map((id) => ({
      id,
      label: labels.get(id) ?? id,
      indexes: groups.get(id) ?? [],
    }))
}

export function layoutGroups(
  items: readonly { id: string; workstream: string }[],
  workstreams: readonly GanttWorkstream[] | undefined,
  rowHeight = GANTT_ROW_HEIGHT,
  groupHeight = GANTT_GROUP_HEIGHT,
) {
  const groups: GanttGroupLayout[] = []
  let y = 0
  for (const group of groupWorkstreams(items, workstreams)) {
    const groupY = y
    y += groupHeight
    const tasks = group.indexes.map((index) => {
      const task = { id: items[index]?.id ?? String(index), index, y, height: rowHeight }
      y += rowHeight
      return task
    })
    groups.push({ id: group.id, label: group.label, y: groupY, height: groupHeight, tasks })
  }
  return { groups, height: y }
}

export function ganttDependencies(items: readonly { id: string; deps?: readonly string[] }[]): GanttDependency[] {
  const ids = new Set(items.map((item) => item.id))
  const seen = new Set<string>()
  const links: GanttDependency[] = []
  for (const item of items) {
    for (const dep of item.deps ?? []) {
      if (!ids.has(dep) || dep === item.id) continue
      const key = `${dep}->${item.id}`
      if (seen.has(key)) continue
      seen.add(key)
      links.push({ fromId: dep, toId: item.id })
    }
  }
  return links
}

export function dependencyCurve(
  from: { x: number; width: number; y: number },
  to: { x: number; y: number },
  rowHeight: number,
) {
  const x1 = from.x + from.width
  const y1 = from.y + rowHeight / 2
  const x2 = to.x
  const y2 = to.y + rowHeight / 2
  const bend = Math.max(12, Math.min(40, Math.abs(x2 - x1) * 0.45))
  const endX = x2 - 4
  const round = (value: number) => Math.round(value * 10) / 10
  return {
    d: `M ${round(x1)} ${round(y1)} C ${round(x1 + bend)} ${round(y1)}, ${round(endX - bend)} ${round(y2)}, ${round(endX)} ${round(y2)}`,
    x: round(x2),
    y: round(y2),
  }
}

